// extractRepoPath builds the per-repo cache key from a remote URL's
// path. The path is used verbatim (minus leading/trailing slashes), so
// /et/<project>/<repo> (or legacy /git/<owner>/<repo>) and
// /gh/<owner>/<repo> live in distinct keyspaces — they're separate
// repos with potentially-different replica sets, even when the
// segments after the prefix match.
//
// entire://host/et/project/repo -> "et/project/repo"
// entire://host/gh/owner/repo   -> "gh/owner/repo"
func extractRepoPath(urlPath string) string {
	return strings.Trim(urlPath, "/")
}

func fatal(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "fatal: "+format+"\n", args...)
	os.Exit(128)
}

// newHTTPClient creates an HTTP client with the given TLS verification setting.
// Used by the token-refresh path; the main request client is built in
// newHTTPProxy with a cluster-aware CheckRedirect.
func newHTTPClient(skipTLSVerify bool) *http.Client {
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: httpclient.NewTransport(skipTLSVerify),
	}
}

// httpProxy handles HTTP requests to Entire server nodes with failover.
type httpProxy struct {
	// nodes is the current replica set. Populated from
	// X-Entire-Replicas headers and the on-disk cache; empty on a cold
	// invocation, in which case infoRefs uses entryURL instead.
	nodes []string
	// entryURL is the cluster entry domain (e.g. https://eu.partial.to).
	// Used by infoRefs when the cached replica set is empty or exhausted —
	// the LB routes to any node, which either serves or 307s to a hosting
	// replica, and the response populates nodes.
	entryURL string
	// clusterHost is the cluster's entry hostname (no scheme, port allowed).
	// Used to decide which redirects are safe to carry Authorization across
	// — same-cluster only.
	clusterHost string
	// cacheHost is the key used when persisting replica sets. Empty
	// disables cache writes.
	cacheHost string
	// repoPath mirrors cacheHost — empty disables cache writes.
	repoPath      string
	path          string // URL path on each node (e.g. "/et/project/repo")

