			return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
		}

		hostPart := parts[0]
		_, host, found := strings.Cut(hostPart, "@")
		if !found {
			host = hostPart
		}

		pathPart := strings.TrimSuffix(parts[1], ".git")
		owner, repo, err := splitOwnerRepo(pathPart)
		if err != nil {
			return nil, err
		}

		return &Info{Protocol: ProtocolSSH, Host: host, Owner: owner, Repo: repo}, nil
	}

	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
	}
	if u.Scheme == "" {
		return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
	}

	pathPart := strings.TrimPrefix(u.Path, "/")
	if u.Scheme == ProtocolEntire {
		// entire:// URLs carry a forge/namespace prefix before owner/repo:
		// entire://host/gh/<owner>/<repo> (github), entire://host/et/<project>/<repo>
		// (entire-native), or legacy /git/<owner>/<repo>. Strip it so Owner/Repo
		// reflect the real repository rather than the forge identifier.
		pathPart = stripForgePrefix(pathPart)
	}
	owner, repo, err := splitOwnerRepo(pathPart)
	if err != nil {
		return nil, err
	}

	return &Info{Protocol: u.Scheme, Host: u.Hostname(), Port: u.Port(), Owner: owner, Repo: repo}, nil
}

// stripForgePrefix removes the leading forge/namespace segment from an entire://
// URL path (e.g. "gh/owner/repo" -> "owner/repo"). Paths without a separator are
// returned unchanged.
func stripForgePrefix(path string) string {
	if _, rest, found := strings.Cut(path, "/"); found {
		return rest
	}
	return path
}

// RedactURL removes credentials and query parameters from a URL for safe logging.
// SCP-style SSH URLs (e.g., git@github.com:org/repo.git) are returned as-is
// since they contain no embedded credentials.
func RedactURL(rawURL string) string {
	// SCP-style SSH: user@host:path — no credentials to redact.
	if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
		return rawURL
	}

	u, err := url.Parse(rawURL)
	if err != nil {
		return "<unparseable>"
