// resolveProviderCheckpointURL builds the checkpoint URL on the configured
// provider's canonical host (e.g. github.com), choosing the transport from
// what's already configured for that host. It is the fallback used when the
// origin/push remote's protocol can't be mapped to a git transport (e.g.
// entire://, file://): the configured checkpoint_remote names a concrete
// provider, so checkpoints go there rather than being misrouted to origin.
//
// Transport precedence:
//  1. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS (the token is the credential).
//  2. An existing remote already targets the provider host -> reuse its scheme,
//     so checkpoints use the same auth the user already has for that endpoint.
//  3. A credential helper is configured for https://<host> -> HTTPS.
//  4. Otherwise SSH (the common default for github/gitlab).
//
// Returns ok=false for providers without a known canonical host, in which case
// the caller should fall back to the origin remote.
func resolveProviderCheckpointURL(ctx context.Context, config *settings.CheckpointRemoteConfig) (string, bool) {
	host, ok := providerHost(config.Provider)
	if !ok {
		return "", false
	}
	url, err := deriveCheckpointURLFromInfo(pickProviderTransport(ctx, host), config)
	if err != nil {
		return "", false
	}
	return url, true
}

// pickProviderTransport returns the protocol/host/port to use when deriving a
// checkpoint URL for host, following the precedence documented on
// resolveProviderCheckpointURL.
func pickProviderTransport(ctx context.Context, host string) *Info {
	if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
		return &Info{Protocol: ProtocolHTTPS, Host: host}
	}
	if info, ok := findRemoteInfoForHost(ctx, host); ok {
		return &Info{Protocol: info.Protocol, Host: info.Host, Port: info.Port}
	}
	if hasCredentialHelper(ctx, "https://"+host) {
		return &Info{Protocol: ProtocolHTTPS, Host: host}
	}
	return &Info{Protocol: ProtocolSSH, Host: host}
}

// findRemoteInfoForHost returns the parsed Info of the first configured git
// remote whose host matches host and whose protocol is a usable git transport
// (ssh/https). entire:// and other non-transport remotes are ignored.
func findRemoteInfoForHost(ctx context.Context, host string) (*Info, bool) {
	names, err := gitremote.ListRemoteNames(ctx)
	if err != nil {
		return nil, false
	}
	for _, name := range names {
		rawURL, err := gitremote.GetRemoteURL(ctx, name)
		if err != nil {
			continue
		}
		info, err := gitremote.ParseURL(rawURL)
		if err != nil {
			continue
		}
		if strings.EqualFold(info.Host, host) && isDerivableProtocol(info.Protocol) {
			return info, true
		}
	}
	return nil, false
}

// hasCredentialHelper reports whether a git credential helper is configured for
// the given URL (via credential.helper urlmatch).
func hasCredentialHelper(ctx context.Context, url string) bool {
	cmd := exec.CommandContext(ctx, "git", "config", "--get-urlmatch", "credential.helper", url)
	output, err := cmd.Output()
	if err != nil {
		return false
	}
	return strings.TrimSpace(string(output)) != ""
}

