1	// Package gitremote provides general-purpose git remote URL utilities:
2	// parsing, resolving, and redacting remote URLs. It has no dependency on
3	// checkpoint, strategy, or settings packages.
4	package gitremote
5	
6	import (
7		"context"
8		"fmt"
9		"net/url"
10		"os/exec"
11		"strings"
12	)
13	
14	const (
15		ProtocolSSH   = "ssh"
16		ProtocolHTTPS = "https"
17		// ProtocolEntire is the scheme of Entire's git remote helper (entire://).
18		// These URLs carry a forge/namespace prefix before owner/repo.
19		ProtocolEntire = "entire"
20	)
21	
22	// Info holds the parsed components of a git remote URL.
23	// Host is the hostname only (never includes a port). Port is empty unless the
24	// source URL specified an explicit non-default port. Callers that need the
25	// combined "host[:port]" form should use HostPort.
26	type Info struct {
27		Protocol string
28		Host     string
29		Port     string
30		Owner    string
31		Repo     string
32	}
33	
34	// HostPort returns Host, or "Host:Port" when Port is non-empty.
35	func (i *Info) HostPort() string {
36		if i.Port == "" {
37			return i.Host
38		}
39		return i.Host + ":" + i.Port
40	}
41	
42	// GetRemoteURL returns the URL configured for the named git remote.
43	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
44		return GetRemoteURLInDir(ctx, "", remoteName)
45	}
46	
47	// ListRemoteNames returns the names of the configured git remotes.
48	func ListRemoteNames(ctx context.Context) ([]string, error) {
49		cmd := exec.CommandContext(ctx, "git", "remote")
50		output, err := cmd.Output()
51		if err != nil {
52			return nil, fmt.Errorf("list git remotes: %w", err)
53		}
54		return strings.Fields(string(output)), nil
55	}
56	
57	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
58	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
59		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
60		if dir != "" {
61			cmd.Dir = dir
62		}
63		output, err := cmd.Output()
64		if err != nil {
65			return "", fmt.Errorf("remote %q not found", remoteName)
66		}
67		return strings.TrimSpace(string(output)), nil
68	}
69	
70	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
71	func ParseURL(rawURL string) (*Info, error) {
72		rawURL = strings.TrimSpace(rawURL)
73	
74		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
75			parts := strings.SplitN(rawURL, ":", 2)
76			if len(parts) != 2 {
77				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
78			}
79	
80			hostPart := parts[0]
81			_, host, found := strings.Cut(hostPart, "@")
82			if !found {
83				host = hostPart
84			}
85	
86			pathPart := strings.TrimSuffix(parts[1], ".git")
87			owner, repo, err := splitOwnerRepo(pathPart)
88			if err != nil {
89				return nil, err
90			}
91	
92			return &Info{Protocol: ProtocolSSH, Host: host, Owner: owner, Repo: repo}, nil
93		}
94	
95		u, err := url.Parse(rawURL)
96		if err != nil {
97			return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
98		}
99		if u.Scheme == "" {
100			return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
101		}
102	
103		pathPart := strings.TrimPrefix(u.Path, "/")
104		if u.Scheme == ProtocolEntire {
105			pathPart = stripForgePrefix(pathPart)
106		}
107		owner, repo, err := splitOwnerRepo(pathPart)
108		if err != nil {
109			return nil, err
110		}
111	
112		return &Info{Protocol: u.Scheme, Host: u.Hostname(), Port: u.Port(), Owner: owner, Repo: repo}, nil
113	}
114	
115	// stripForgePrefix removes the leading forge/namespace segment from an entire://
116	// URL path (e.g. "gh/owner/repo" -> "owner/repo"). Paths without a separator are
117	// returned unchanged.
118	func stripForgePrefix(path string) string {
119		if _, rest, found := strings.Cut(path, "/"); found {
120			return rest
121		}
122		return path
123	}
124	
125	// RedactURL removes credentials and query parameters from a URL for safe logging.
126	// SCP-style SSH URLs (e.g., git@github.com:org/repo.git) are returned as-is
127	// since they contain no embedded credentials.
128	func RedactURL(rawURL string) string {
129		// SCP-style SSH: user@host:path — no credentials to redact.
130		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
131			return rawURL
132		}
133	
134		u, err := url.Parse(rawURL)
135		if err != nil {
136			return "<unparseable>"
137		}
138		u.User = nil
139		u.RawQuery = ""
140		return u.Scheme + "://" + u.Host + u.Path
141	}
142	
143	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
144	// Returns an empty string if the URL cannot be parsed.
145	func ExtractOwnerFromRemoteURL(rawURL string) string {
146		info, err := ParseURL(rawURL)
147		if err != nil {
148			return ""
149		}
150		return info.Owner
151	}
152	
153	// ResolveRemoteRepo returns the host, owner, and repo name for the given git remote.
154	// It parses the remote URL (SSH or HTTPS) and extracts the components.
155	// For example, git@github.com:org/my-repo.git returns ("github.com", "org", "my-repo").
156	func ResolveRemoteRepo(ctx context.Context, remoteName string) (host, owner, repo string, err error) {
157		rawURL, err := GetRemoteURL(ctx, remoteName)
158		if err != nil {
159			return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
160		}
161		info, err := ParseURL(rawURL)
162		if err != nil {
163			return "", "", "", fmt.Errorf("parse remote URL: %w", err)
164		}
165		return info.Host, info.Owner, info.Repo, nil
166	}
167	
168	func splitOwnerRepo(path string) (string, string, error) {
169		path = strings.TrimSuffix(path, ".git")
170		parts := strings.SplitN(path, "/", 2)
171		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
172			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
173		}
174		return parts[0], parts[1], nil
175	}

