			g := newGitHookContext(cmd.Context(), "pre-push")
			defer g.span.End()
			g.logInvoked(slog.String("remote", remote))

			hookErr := g.strategy.PrePush(g.ctx, remote)
			g.logCompleted(hookErr)

			return nil
		},
	}
}

